package deploy

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/EscapeVelocityOperations/hatch-cli/internal/ci"
	"github.com/EscapeVelocityOperations/hatch-cli/internal/ci/workflowtest"
)

// h-cmzf.1/.2/.3: a workflow generated by `hatch ci` reaches the upload with
// the exact parameters it was generated with. The generated script runs under
// /bin/sh against a fake binary; the argv it received is then fed to the real
// deploy command with a fake API, from a checkout whose .hatch.toml names a
// different egg (and with no confirmation possible, as on a runner).
func TestGeneratedWorkflow_ReachesUploadWithGeneratedParams(t *testing.T) {
	const startCmd = `node server.js --port $PORT "$(printf vigie)" 'a: b'`
	for _, provider := range []string{"github", "gitlab"} {
		t.Run(provider, func(t *testing.T) {
			sum := workflowtest.FakeHatchSHA256()
			wf, err := ci.RenderWorkflow(provider, ci.WorkflowParams{
				App: "fixture-stage", Runtime: "node", DeployTarget: "build out", StartCommand: startCmd,
				CLI: ci.CLIRelease{Version: "v0.21.0", SHA256AMD64: sum, SHA256ARM64: sum},
			})
			if err != nil {
				t.Fatal(err)
			}
			d, err := workflowtest.Extract(provider, wf.Content)
			if err != nil {
				t.Fatal(err)
			}

			checkout := t.TempDir()
			if err := os.WriteFile(filepath.Join(checkout, ".hatch.toml"), []byte("[app]\nslug = \"fixture-prod\"\n"), 0o644); err != nil {
				t.Fatal(err)
			}
			if err := os.MkdirAll(filepath.Join(checkout, "build out"), 0o755); err != nil {
				t.Fatal(err)
			}
			if err := os.WriteFile(filepath.Join(checkout, "build out", "server.js"), []byte("//"), 0o644); err != nil {
				t.Fatal(err)
			}

			res, err := workflowtest.Run(d, checkout, workflowtest.FakeHatch, map[string]string{"PORT": "49123"})
			if err != nil || res.Err != nil {
				t.Fatalf("%v %v\n%s", err, res.Err, res.Output)
			}
			if len(res.Argv) == 0 || res.Argv[0] != "deploy" {
				t.Fatalf("argv = %q", res.Argv)
			}

			var gotSlug, gotRuntime, gotStart string
			deps = &Deps{
				GetToken: func() (string, error) { return "fake-token", nil },
				GetCwd:   func() (string, error) { return checkout, nil },
				NewAPIClient: newMockAPIClient(&mockAPIClient{
					uploadArtifactFn: func(slug string, _ []byte, rt, sc string) error {
						gotSlug, gotRuntime, gotStart = slug, rt, sc
						return nil
					},
				}),
				Confirm: func(string) bool { t.Error("a CI deploy must not prompt"); return false },
			}
			t.Cleanup(func() { deps = defaultDeps(); appSlug, deployTarget, runtime, startCommand = "", "", "", "" })
			oldDir, _ := os.Getwd()
			if err := os.Chdir(checkout); err != nil {
				t.Fatal(err)
			}
			t.Cleanup(func() { os.Chdir(oldDir) })

			cmd := NewCmd()
			cmd.SetArgs(res.Argv[1:])
			var runErr error
			captureOutput(func() { runErr = cmd.Execute() })
			if runErr != nil {
				t.Fatalf("deploy %q: %v", res.Argv[1:], runErr)
			}
			if gotSlug != "fixture-stage" || gotRuntime != "node" || gotStart != startCmd {
				t.Errorf("upload got slug=%q runtime=%q start=%q; want fixture-stage, node, %q", gotSlug, gotRuntime, gotStart, startCmd)
			}
		})
	}
}

// h-cmzf.2: --app deploys to the named egg even when .hatch.toml names another.
func TestRunDeploy_AppFlagOverridesHatchToml(t *testing.T) {
	tmp := t.TempDir()
	if err := os.WriteFile(filepath.Join(tmp, ".hatch.toml"), []byte("[app]\nslug = \"fixture-prod\"\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	var uploaded string
	deps = &Deps{
		GetToken: func() (string, error) { return "tok", nil },
		GetCwd:   func() (string, error) { return tmp, nil },
		NewAPIClient: newMockAPIClient(&mockAPIClient{
			uploadArtifactFn: func(slug string, _ []byte, _, _ string) error { uploaded = slug; return nil },
		}),
	}
	t.Cleanup(func() { deps = defaultDeps(); appSlug, deployTarget, runtime, startCommand = "", "", "", "" })
	oldDir, _ := os.Getwd()
	os.Chdir(tmp)
	t.Cleanup(func() { os.Chdir(oldDir) })
	if err := os.WriteFile(filepath.Join(tmp, ".hatchignore"), []byte(".hatch.toml\n"), 0o644); err != nil {
		t.Fatal(err)
	}

	cmd := NewCmd()
	cmd.SetArgs([]string{"--app", "fixture-stage", "--runtime", "static", "--deploy-target", tmp})
	var err error
	captureOutput(func() { err = cmd.Execute() })
	if err != nil {
		t.Fatal(err)
	}
	if uploaded != "fixture-stage" {
		t.Errorf("uploaded to %q, want fixture-stage", uploaded)
	}
	if b, _ := os.ReadFile(filepath.Join(tmp, ".hatch.toml")); string(b) != "[app]\nslug = \"fixture-prod\"\n" {
		t.Errorf(".hatch.toml rewritten: %q", b)
	}
}
